// 카톡 확정 응답 직후 실행 (예약 데이터에서 알림 내용 구성)
// 입력: calcom-booking 노드의 응답 또는 respond-success 직전 데이터

const booking = $json.json || $json;
const name = booking.name || '고객';
const start = booking.start || '';
const email = booking.email || '';
const notes = booking.notes || '';

const dt = new Date(start);
const kst = new Date(dt.getTime() + 9 * 3600 * 1000);
const when = isNaN(dt.getTime())
  ? start
  : kst.toISOString().replace('T', ' ').slice(0, 16) + ' KST';

return [{
  json: {
    chatId: $env.TELEGRAM_CHAT_ID,
    text: `📅 *신규 예약 확정*

👤 고객: ${name}
🕐 일시: ${when}
📧 이메일: ${email}
📝 메모: ${notes || '-'}

(자동으로 생성되었습니다)`
  }
}];
